solution.code:
import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const nums = input[0].split(" ").map(Number);

// 比較関数を渡さないと文字列として並ぶ（"10" < "9" になる）
nums.sort((x, y) => x - y);
console.log(nums.join(" "));
